-- Run ONCE in a Snowsight worksheet as ACCOUNTADMIN. Creates PC3's service user (key-pair auth, same FC_ROLE).
USE ROLE ACCOUNTADMIN;
CREATE USER IF NOT EXISTS FC_PC3
  TYPE = SERVICE
  DEFAULT_ROLE = FC_ROLE
  DEFAULT_WAREHOUSE = FC_WH
  DEFAULT_NAMESPACE = FLASHCROWD.CORE
  RSA_PUBLIC_KEY = '';
GRANT ROLE FC_ROLE TO USER FC_PC3;
DESC USER FC_PC3;   -- check: RSA_PUBLIC_KEY_FP starts with SHA256:
